   116  page::orientation_enum page::orientation() const
   117  {
   118      const int rotation = d->page->getRotate();
   119      switch (rotation) {
   120      case 90:
   121          return landscape;
   122          break;
   123      case 180:
   124          return upside_down;
   125          break;
   126      case 270:
   127          return seascape;
   128          break;
   129      default:
   130          return portrait;
   131      }
   132  }
