   149  /**
   150   Returns the size of one rect of the page.
   151
   152   \returns the size of the specified page rect
   153   */
   154  rectf page::page_rect(page_box_enum box) const
   155  {
   156      const PDFRectangle *r = nullptr;
   157      switch (box) {
   158      case media_box:
   159          r = d->page->getMediaBox();
   160          break;
   161      case crop_box:
   162          r = d->page->getCropBox();
   163          break;
   164      case bleed_box:
   165          r = d->page->getBleedBox();
   166          break;
   167      case trim_box:
   168          r = d->page->getTrimBox();
   169          break;
   170      case art_box:
   171          r = d->page->getArtBox();
   172          break;
   173      }
   174      if (r) {
   175          return detail::pdfrectangle_to_rectf(*r);
   176      }
   177      return rectf();
   178  }
